def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove any spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Initialize an empty list to store the separate groups of parentheses
    separate_groups = []

    # Step 3: Iterate through the input string and identify each group of parentheses
    start = 0
    count = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1
        if count == 0:
            separate_groups.append(paren_string[start:i+1])
            start = i + 1

    # Step 4: Check if each group of parentheses is balanced
    def is_balanced(group):
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack.pop() != '(':
                    return False
        return not stack

    # Step 5: Append the balanced groups of parentheses to the list
    balanced_groups = [group for group in separate_groups if is_balanced(group)]

    # Step 6: Return the list of separate groups of parentheses
    return balanced_groups
